"""Fixed vocabulary of the project: option keys, formats, renders, conditions
and the fixed question/answer strings in English and Bengali."""

from __future__ import annotations

# Option keys stored on every item (per language block).
OPTION_KEYS: tuple[str, ...] = ("correct", "literal", "plausible")
NONE_KEY = "none"  # synthetic "None of these" option used by the `none` format

# Question formats generated by the builder.
#   normal   : What does X mean?        options {correct, literal}      gold correct
#   negative : What does X NOT mean?    options {correct, literal}      gold literal
#   none     : What does X mean?        options {literal, plausible, none}  gold none
#   meaning  : What does this proverb mean? (no conversation)
#              options {proverb meaning, literal}                        gold correct
FORMATS: tuple[str, ...] = ("normal", "negative", "none", "meaning")

FORMAT_OPTIONS: dict[str, tuple[str, ...]] = {
    "normal": ("correct", "literal"),
    "negative": ("correct", "literal"),
    "none": ("literal", "plausible", NONE_KEY),
    "meaning": ("correct", "literal"),
}

FORMAT_GOLD: dict[str, str] = {
    "normal": "correct",
    "negative": "literal",
    "none": NONE_KEY,
    "meaning": "correct",
}

# Chance level per format (with the default option sets above).
FORMAT_CHANCE: dict[str, float] = {"normal": 0.5, "negative": 0.5, "none": 1 / 3, "meaning": 0.5}

# How the proverb is shown inside the conversation.
#   romanised : romanised proverb (default)
#   gloss     : romanised proverb + ("literal English gloss")
#   gloss_only: the literal English gloss replaces the proverb
#   respelled : romanised proverb with false-friend words respelled
#   bengali   : Bengali-script proverb (inside English turns for lang=en;
#               the whole item is Bengali for lang=bn)
RENDERS: tuple[str, ...] = ("romanised", "gloss", "gloss_only", "respelled", "bengali")

LANGS: tuple[str, ...] = ("en", "bn")

# Controls
#   none        : normal prompt
#   no_question : the question line is removed (tests answer-option artefacts)
CONTROLS: tuple[str, ...] = ("none", "no_question")

LETTERS: tuple[str, ...] = ("A", "B", "C", "D", "E")

REGIONS: tuple[str, ...] = ("WB", "BD", "both")

SPLITS: tuple[str, ...] = ("test", "nvt", "train", "gepa_dev", "excluded")

ANNOTATOR_LABELS: tuple[str, ...] = ("correct", "literal", "plausible", "none", "unsure")

# Experimental conditions (intervention ladder).
CONDITIONS: dict[str, str] = {
    "C0": "Base model, no intervention",
    "C1a": "Simple persona system prompt",
    "C1b": "Rich personalisation system prompt",
    "C1c": "GEPA-optimised system prompt",
    "C2": "LoRA fine-tune on general cultural data",
    "C3": "LoRA fine-tune on proverb-style data",
    "C4": "Two-stage: C2 then C3",
    "C5": "DPO: correct meaning preferred over literal reading",
    "C6": "Mixture of LoRA experts",
    "REF": "Frontier model, zero-shot (ceiling)",
}

